#include <LiquidCrystal.h>

// LCD1 - 20x4
// RS, E, D4, D5, D6, D7
LiquidCrystal lcd(13, 12, 11, 10, 9, 8);

// LCD2 - 16x2
// RS, E, D4, D5, D6, D7

LiquidCrystal lcd2(A4, A5, 11, 10, 9, 8);

const int Fan_Pin = 6;
const int Pump_Pin = 7;

void setup()
{
  // LCD1
    lcd.begin(20, 4);

      lcd.setCursor(0, 0);
        lcd.print("IoT SMART FARMING");

          // LCD2
            lcd2.begin(16, 2);

              lcd2.setCursor(0, 0);
                lcd2.print("Reg: 24BCE8046");

                  lcd2.setCursor(0, 1);
                    lcd2.print("Name: U Hari");

                      pinMode(Fan_Pin, OUTPUT);
                        pinMode(Pump_Pin, OUTPUT);
                          pinMode(A1, INPUT);
                          }

                          void loop()
                          {
                            // Temperature Sensing
                              int S1 = analogRead(A0);
                                float mV = (S1 / 1023.0) * 5000;
                                  int Temp = mV / 10;

                                    lcd.setCursor(0, 1);
                                      lcd.print(" T=");
                                        lcd.print(Temp);
                                          lcd.print("'C  ");

                                            // Rain Sensing
                                              int R = digitalRead(A1);

                                                if (R == 0)
                                                  {
                                                      lcd.setCursor(10, 1);
                                                          lcd.print(" R=NO ");
                                                            }

                                                              if (R == 1)
                                                                {
                                                                    lcd.setCursor(10, 1);
                                                                        lcd.print(" R=YES ");
                                                                          }

                                                                            // Soil Moisture
                                                                              int S3 = analogRead(A2);
                                                                                int SM = S3 / 10;

                                                                                  lcd.setCursor(0, 2);
                                                                                    lcd.print(" S=");
                                                                                      lcd.print(SM);
                                                                                        lcd.print("%  ");

                                                                                          // Air Humidity
                                                                                            int S4 = analogRead(A3);
                                                                                              int H = S4 / 10;

                                                                                                lcd.setCursor(10, 2);
                                                                                                  lcd.print(" H=");
                                                                                                    lcd.print(H);
                                                                                                      lcd.print("%  ");

                                                                                                        // Fan
                                                                                                          if (Temp > 30)
                                                                                                            {
                                                                                                                digitalWrite(Fan_Pin, HIGH);

                                                                                                                    lcd.setCursor(0, 3);
                                                                                                                        lcd.print(" Fan:ON  ");
                                                                                                                          }
                                                                                                                            else
                                                                                                                              {
                                                                                                                                  digitalWrite(Fan_Pin, LOW);

                                                                                                                                      lcd.setCursor(0, 3);
                                                                                                                                          lcd.print(" Fan:OFF ");
                                                                                                                                            }

                                                                                                                                              // Pump
                                                                                                                                                if (SM < 40 && R == 0)
                                                                                                                                                  {
                                                                                                                                                      digitalWrite(Pump_Pin, HIGH);

                                                                                                                                                          lcd.setCursor(10, 3);
                                                                                                                                                              lcd.print(" Motor:ON  ");
                                                                                                                                                                }
                                                                                                                                                                  else
                                                                                                                                                                    {
                                                                                                                                                                        digitalWrite(Pump_Pin, LOW);

                                                                                                                                                                            lcd.setCursor(10, 3);
                                                                                                                                                                                lcd.print(" Motor:OFF ");
                                                                                                                                                                                  }
                                                                                                                                                                                  }
